class McpClient {
  readonly config: ServerConfig;
  readonly child: ChildProcessWithoutNullStreams;
  private nextId = 1;
  private pending = new Map<number, {
    resolve: (value: any) => void;
    reject: (error: Error) => void;
    timer: ReturnType<typeof setTimeout>;
  }>();
  private stderrTail = "";

  constructor(config: ServerConfig) {
    this.config = config;
    this.child = spawn(config.command, config.args, {
      env: process.env,
      stdio: ["pipe", "pipe", "pipe"],
      windowsHide: true,
    });
    this.child.stderr.setEncoding("utf8");
    this.child.stderr.on("data", (chunk: string) => {
      this.stderrTail = (this.stderrTail + chunk).slice(-8192);
    });
    createInterface({ input: this.child.stdout }).on("line", (line) => {
      if (!line.trim()) return;
      let message: JsonRpcResponse;
      try {
        message = JSON.parse(line);
      } catch {
        this.failAll(new Error(`${config.name}: invalid JSON-RPC response`));
        return;
      }
      if (typeof message.id !== "number") return;
      const request = this.pending.get(message.id);
      if (!request) return;
      this.pending.delete(message.id);
      clearTimeout(request.timer);
      if (message.error) {
        request.reject(new Error(`${config.name}: ${message.error.message ?? "MCP request failed"}`));
      } else {
        request.resolve(message.result);
      }
    });
    this.child.once("error", (error) => this.failAll(error));
    this.child.once("exit", (code, signal) => {
      this.failAll(new Error(
        `${config.name}: MCP process exited (code=${code}, signal=${signal})${this.stderrTail ? `: ${this.stderrTail}` : ""}`,
      ));
    });
  }

  private failAll(error: Error): void {
    for (const request of this.pending.values()) {
      clearTimeout(request.timer);
      request.reject(error);
    }
    this.pending.clear();
  }

  notify(method: string, params?: unknown): void {
    this.child.stdin.write(JSON.stringify({ jsonrpc: "2.0", method, ...(params === undefined ? {} : { params }) }) + "\n");
  }

  request(method: string, params: unknown, timeoutMs = this.config.startupTimeoutMs, signal?: AbortSignal): Promise<any> {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        signal?.removeEventListener("abort", abort);
        reject(new Error(`${this.config.name}: ${method} timed out after ${timeoutMs}ms`));
      }, timeoutMs);
      const abort = () => {
        this.pending.delete(id);
        clearTimeout(timer);
        this.notify("notifications/cancelled", { requestId: id, reason: "Pi tool call aborted" });
        reject(new Error(`${this.config.name}: ${method} aborted`));
      };
      if (signal?.aborted) return abort();
      signal?.addEventListener("abort", abort, { once: true });
      this.pending.set(id, {
        timer,
        resolve: (value) => {
          signal?.removeEventListener("abort", abort);
          resolve(value);
        },
        reject: (error) => {
          signal?.removeEventListener("abort", abort);
          reject(error);
        },
      });
      this.child.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
    });
  }

  async initialize(): Promise<Array<{ name: string; description?: string; inputSchema?: object }>> {
    await this.request("initialize", {
      protocolVersion: PROTOCOL_VERSION,
      capabilities: {},
      clientInfo: { name: "narada-pi-carrier", version: "1" },
    });
    this.notify("notifications/initialized");
    const listed = await this.request("tools/list", {});
    if (!Array.isArray(listed?.tools)) {
      throw new Error(`${this.config.name}: tools/list returned no tools array`);
    }
    return listed.tools;
  }

  close(): void {
    this.failAll(new Error(`${this.config.name}: session closed`));
    if (!this.child.killed) this.child.kill();
  }
}

export default function naradaMcpCarrier(pi: any): void {
  let clients: McpClient[] = [];
  let started = false;

  const pollMariciInbox = async (request: NaradaMariciInboxPollRequest): Promise<void> => {
    try {
      const client = clients.find((candidate) => candidate.config.name === "mcp-loader");
      if (!client) throw new Error("mcp-loader is not attached");
      const authority = startupAuthority(SERVERS.filter(shouldBootstrapServer));
      if (!authority.identity || authority.identity === "anonymous" || authority.identity === "unknown") {
        throw new Error("no mechanically admitted Marici recipient identity");
      }
      const inspection = await client.request("tools/call", {
        name: "mcp_loader_inspect_binding_tool",
        arguments: {
          site_root: request.siteRoot,
          binding_id: "marici-epistemic-graph",
          tool_name: "epistemic_graph_query",
        },
      }, 10_000);
      const leaseEnvelope = inspection?.structuredContent ?? {};
      const schemaLease = leaseEnvelope?.schema_lease;
      if (typeof schemaLease !== "string" || !schemaLease) throw new Error("epistemic graph query lease unavailable");
      const sequences: number[] = [];
      let count = 0;
      for (let page = 0; page < 16; page += 1) {
        const called = await client.request("tools/call", {
          name: "mcp_loader_call_binding_tool",
          arguments: {
            site_root: request.siteRoot,
            binding_id: "marici-epistemic-graph",
            tool_name: "epistemic_graph_query",
            schema_lease: schemaLease,
            arguments: {
              kinds: ["narada.epistemic:communication", "marici:communication", "communication"],
              recipient: authority.identity,
              after_sequence: request.sinceSequence,
              include_body: false,
              compact: true,
              limit: 256,
              offset: page * 256,
            },
          },
        }, 15_000);
        const loaderEnvelope = called?.structuredContent ?? {};
        const query = loaderEnvelope?.result?.structuredContent ?? loaderEnvelope?.result ?? {};
        if (query?.schema !== "narada.epistemic.query.v1" || !Array.isArray(query?.items)) {
          throw new Error("epistemic graph returned no bounded communication page");
        }
        count += query.items.length;
        sequences.push(...query.items
          .map((item: any) => typeof item?.event_id === "string"
            ? Number(item.event_id.match(/^ev-(\d+)-/)?.[1] ?? NaN)
            : NaN)
          .filter((value: number) => Number.isSafeInteger(value) && value >= 0));
        if (query.items.length < 256) break;
        if (page === 15) throw new Error("Marici inbox count exceeded the 4096-message polling bound");
      }
      const newCursor = sequences.length > 0 ? Math.max(request.sinceSequence, ...sequences) : request.sinceSequence;
      request.resolve({
        count,
        previousCursor: request.sinceSequence,
        newCursor,
        source: "epistemic_graph_communication",
      });
    } catch (error) {
      request.reject(error instanceof Error ? error : new Error(String(error)));
    }
  };
  pi.events.on(NARADA_MARICI_INBOX_POLL_EVENT, pollMariciInbox);

  pi.on("session_start", async (_event: unknown, ctx: any) => {
    if (started) return;
    started = true;
    const nextClients: McpClient[] = [];
    let startupRuntime: StartupRuntime = { loader: "unknown", proxy: "unknown" };
    const bootstrapConfigs = SERVERS.filter(shouldBootstrapServer);
    const authority = startupAuthority(bootstrapConfigs);
    ctx?.ui?.notify?.(
      startupDiagnostic(authority, {
        mcp: "loading",
        runtime: { loader: "checking", proxy: "checking" },
        remediation: "waiting for mcp-loader initialization",
      }),
      "info",
    );
    try {
      const inventories: Array<{ client: McpClient; tools: any[]; runtime: StartupRuntime }> = [];
      for (const config of bootstrapConfigs) {
        const client = new McpClient(config);
        try {
          const tools = await client.initialize();
          inventories.push({
            client,
            tools,
            runtime: await inspectStartupRuntime(client, tools),
          });
          nextClients.push(client);
        } catch (error) {
          client.close();
          const message = error instanceof Error ? error.message : String(error);
          ctx?.ui?.notify?.(`Narada MCP server ${config.name} failed: ${message}`, "warning");
        }
      }
      if (inventories.length === 0) {
        throw new Error("No admitted MCP server completed startup");
      }

      startupRuntime = inventories.reduce<StartupRuntime>(
        (current, inventory) => ({
          loader: inventory.runtime.loader !== "unknown" ? inventory.runtime.loader : current.loader,
          proxy: inventory.runtime.proxy !== "unknown" ? inventory.runtime.proxy : current.proxy,
        }),
        { loader: "unknown", proxy: "unknown" },
      );

      const schemaDiagnostics = inventories.map(({ client, tools }) => ({
        server: client.config.name,
        toolCount: tools.length,
        schemaChars: tools.reduce(
          (total, tool) => total + JSON.stringify(tool?.inputSchema ?? {}).length,
          0,
        ),
      }));
      const bootstrapToolCount = schemaDiagnostics.reduce((total, row) => total + row.toolCount, 0);
      const bootstrapSchemaChars = schemaDiagnostics.reduce((total, row) => total + row.schemaChars, 0);
      if (bootstrapToolCount > MAX_BOOTSTRAP_TOOLS || bootstrapSchemaChars > MAX_BOOTSTRAP_SCHEMA_CHARS) {
        throw new Error(`narada_pi_bootstrap_context_budget_exceeded:${JSON.stringify({
          bootstrapToolCount,
          bootstrapSchemaChars,
          maxBootstrapTools: MAX_BOOTSTRAP_TOOLS,
          maxBootstrapSchemaChars: MAX_BOOTSTRAP_SCHEMA_CHARS,
          servers: schemaDiagnostics,
        })}`);
      }

      const existing = new Set((pi.getAllTools?.() ?? []).map((tool: any) => tool.name));
      const counts = new Map<string, number>();
      for (const { client, tools } of inventories) {
        for (const tool of tools) {
          if (typeof tool?.name !== "string" || !tool.name) {
            throw new Error(`${client.config.name}: tools/list contained an invalid tool name`);
          }
          counts.set(tool.name, (counts.get(tool.name) ?? 0) + 1);
        }
      }

      const exposed = new Set<string>();
      for (const { client, tools } of inventories) {
        for (const tool of tools) {
          const serverPrefix = client.config.name.replace(/[^A-Za-z0-9_-]/g, "_");
          const exposedName = counts.get(tool.name) === 1 && !existing.has(tool.name)
            ? tool.name
            : `${serverPrefix}__${tool.name}`;
          if (existing.has(exposedName) || exposed.has(exposedName)) {
            throw new Error(`Narada MCP qualified tool name collision: ${exposedName}`);
          }
          exposed.add(exposedName);
          pi.registerTool({
            name: exposedName,
            label: tool.title ?? exposedName,
            description: `${tool.description ?? "MCP tool"} (server: ${client.config.name}; MCP name: ${tool.name}).${carrierRoutingGuidance(client.config.name, tool.name)}`,
            parameters: tool.inputSchema ?? { type: "object", additionalProperties: true },
            execute: async (_toolCallId: string, params: unknown, signal: AbortSignal) => {
              const result = await client.request("tools/call", { name: tool.name, arguments: params ?? {} }, 120000, signal);
              const rawText = resultText(result);
              const content = preservesDeliveredContent(result)
                ? result.content
                : result?.structuredContent !== undefined
                ? [{ type: "text", text: JSON.stringify(result.structuredContent) }]
                : Array.isArray(result?.content) && result.content.length > 0
                  ? result.content
                  : [{ type: "text", text: JSON.stringify(result ?? null) }];
              const bounded = boundedModelContent(result, content, rawText);
              return {
                content: bounded.content,
                details: {
                  mcpServer: client.config.name,
                  isError: result?.isError === true,
                  structuredSchema: result?.structuredContent?.schema ?? null,
                  continuation: result?.structuredContent?.result?.next_offset ?? result?.structuredContent?.next_offset ?? null,
                  uiSummary: summarizeMcpResult(result, resultText({ content })),
                  collapseByDefault: collapseMcpResultByDefault(),
                  expandedText: bounded.expandedText,
                },
                isError: result?.isError === true,
              };
            },
            renderResult: (result: any, options: { expanded: boolean }, theme: any) => {
              const fullText = result?.details?.expandedText ?? resultText(result);
              if (options.expanded || result?.details?.collapseByDefault === false) {
                return textComponent(fullText || JSON.stringify(result?.details ?? null));
              }
              const summary = result?.details?.uiSummary ?? summarizeMcpResult(result, fullText);
              return textComponent(mutedText(theme, `${summary} — ctrl+o to expand`));
            },
          });
        }
      }
      clients = nextClients;
      ctx?.ui?.notify?.(
        startupDiagnostic(authority, {
          mcp: "attached",
          runtime: startupRuntime,
          remediation: startupRemediation(authority, startupRuntime, "attached"),
        }),
        "info",
      );
      ctx?.ui?.notify?.(
        `Narada MCP: ${exposed.size} bootstrap tools from ${clients.length} servers (${bootstrapSchemaChars} schema chars); Site capabilities are lazy through mcp-loader`,
        "info",
      );
    } catch (error) {
      for (const client of nextClients) client.close();
      clients = [];
      started = false;
      ctx?.ui?.notify?.(
        startupDiagnostic(authority, {
          mcp: "failed",
          runtime: startupRuntime,
          remediation: startupRemediation(authority, startupRuntime, "failed"),
        }),
        "warning",
      );
      const message = error instanceof Error ? error.message : String(error);
      ctx?.ui?.notify?.(`Narada MCP startup failed: ${message}`, "error");
      throw error;
    }
  });

  pi.on("session_shutdown", () => {
    for (const client of clients) client.close();
    clients = [];
    started = false;
    pi.events.off?.(NARADA_MARICI_INBOX_POLL_EVENT, pollMariciInbox);
  });
}
